import assert from 'node:assert/strict';import {setup} from './anvil-orchard-custody-source.mjs';
export const tail=(h,tick)=>{h.sim.state.tick=tick;h.owner.step(1/60,tick);h.owner.publishCompletedOrchardContacts(h.owner.completedOrchardTail(),()=>h.owner.drainContactImpacts());};
export async function ready(){const h=await setup();assert.equal(h.accept(),4);assert.equal(h.owner.requestOrchardFiniteRelease(h.frame,1,h.sim.state),true);for(let i=1;i<=30;i++)tail(h,i);h.pod=h.sim.state.entityList.find(e=>e.data?.orchardKind==='pod');assert.equal(h.owner.readOrchardPodReady(h.pod,h.sim.state),null);h.initialQuaternion=h.owner.records.get(h.pod.id).body.rotation();const stage=h.owner.prepareOrchardPodHandoff(h.frame,h.pod,1,h.sim.state);assert.ok(stage);assert.equal(stage.commit(),true);return h;}
